// === Tab: mySketch ===
// Attractor_20.0

let N = 100000 ; let RR = 100 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let R ; let A ; let I ; let KX ; let KY ; 

function setup(){
  createCanvas(1112, 834) ; noSmooth() ; background(0) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(1112) ; Y[I] = random(834) ;
  }//I
}//setup()

function draw(){
  background(0) ;
	translate(250, 250);
  stroke(255, 0, 255) ;
    for ( I = 0 ; I < N ; I++ ){
        KX = X[I]-X[0] ; KY = Y[I]-Y[0] ;
        KY = KY/2+RR ;
        R = sqrt(pow(KX,2)+pow(KY,2)) ;
        A = atan(KY/KX) ;
        if ( KX < 0 ){ A = A+PI ; }
        if ( KX >= 0 && KY < 0 ){ A = A+(2*PI) ; }
        A = A*2 ;
        KX = R*cos(A) ; KY = R*sin(A) ;
        X[I] = KX+X[0] ; Y[I] = KY+Y[0] ;
        point(X[I]-X[0]+300,Y[I]-Y[0]+300) ;
    }//I
    stroke(0, 255, 255) ;
    for ( I = 0 ; I < N ; I++ ){
        KX = X[I]-X[1] ; KY = Y[1]-Y[I] ;
        KY = KY/2+RR ;
        R = sqrt(pow(KX,2)+pow(KY,2)) ;
        A = atan(KY/KX) ;
        if ( KX < 0 ){ A = A+PI ; }
        if ( KX >= 0 && KY < 0 ){ A = A+(2*PI) ; }
        A = A*2 ;
        KX = R*cos(A) ; KY = R*sin(A) ;
        X[I] = X[1]+KX ; Y[I] = Y[1]-KY ;
        point(X[I]-X[0]+300,Y[I]-Y[0]+300) ;
    }//I
}//draw()

function mousePressed(){ setup() ; }

